const PREC=[{"id":"P1","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Cremiges Knoblauch-Hähnchen aus dem Ofen","k":610,"p":90,"t":"ca. 30 Min","z":["300 g Hähnchenbrust (gekocht & zerrupft)","250 g körniger Frischkäse","1–2 EL Knoblauchsoße oder Knoblauchdip","1 TL Knoblauchpulver","1 Stange Sellerie","½ Zwiebel","30 g Cheddar (gerieben)","Optional: 150 g ungekochter Reis (als Beilage)","Salz & Pfeffer nach Geschmack"],"s":["Hähnchenbrust in Brühe garen.","Währenddessen Frischkäse, Knoblauchsoße und Knoblauchpulver im Mixer pürieren.","Die Soße kalt stellen.","Das gegarte Fleisch mit zwei Gabeln zerzupfen und in eine Schüssel geben.","Soße darübergeben.","Sellerie und Zwiebel unterheben.","Alles in eine Auflaufform füllen.","Käse darüberstreuen.","Kurz überbacken, bis der Käse zerlaufen ist."],"note":"Reis ist optional als Beilage und in den Nährwerten nicht enthalten. Ob die Nährwerte pro Portion oder für alles gelten, ist nicht angegeben."},{"id":"P2","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Dessert","n":"Protein-Bohnen-Brownies (ohne Mehl)","k":120,"p":11,"t":"ca. 30 Min","w":0.125,"pt":"ca. 8 Portionen","u":"pro Portion","z":["1 Dose Kidneybohnen (abgespült & abgetropft)","2 reife Bananen","2 Cups Proteinpulver (z. B. Vanille)","2 Eier","2 TL Backkakao","⅓ Packung Backpulver","1 EL Honig","1 Prise Salz"],"s":["Ofen auf 180 °C Ober-/Unterhitze vorheizen.","Alle Zutaten zu einem Teig vermengen.","Teig in eine Form füllen, z. B. eine kleine Auflaufform.","Backen. Die Zeit hängt von der Formgröße ab, per Stäbchenprobe prüfen.","Kurz abkühlen lassen.","Mit etwas Proteinpulver bestäuben."],"note":"Ergibt 8 Stücke. Nährwerte pro Stück: ca. 120 kcal, ca. 10–11 g Protein, ca. 2,5 g Fett; Kohlenhydrate nicht angegeben. Die Backzeit ist nicht genannt."},{"id":"P3","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Snack / Pause","n":"Knusprige Gurkensticks mit Käse","k":315,"p":20,"t":"ca. 30 Min","z":["1 Glas Gewürzgurken (ca. 360 g Abtropfgewicht)","50 g Cheddar","1 Ei","Gewürze nach Geschmack (z. B. Paprika, Knoblauchpulver, Salz, Pfeffer)"],"s":["Ofen auf 200 °C Ober-/Unterhitze vorheizen.","Gurken im Mixer zerkleinern.","Die Gurkenmasse kräftig ausdrücken, bis fast keine Flüssigkeit mehr austritt.","Ei, geriebenen Cheddar und Gewürze untermengen.","Aus der Masse kleine Sticks formen.","Sticks auf ein mit Backpapier belegtes Blech legen.","Etwa 20 Minuten backen, bis sie goldbraun und knusprig sind.","Nach Wunsch mit Dip servieren, z. B. Knoblauch- oder Joghurt-Dip."],"note":"Menge für 1 Blech, Portionszahl nicht angegeben. Nährwerte gelten für das ganze Rezept. Dip ist optional."},{"id":"P4","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Cremige BBQ-Hähnchen-Pasta aus dem Ofen","k":552,"p":53,"t":"50 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["200 g Pasta nach Wahl (Trockengewicht)","600 g Hähnchenbrust, gewürfelt","1 Zwiebel","2 Paprika","1 Dose (400 g) gehackte Tomaten","100 ml Wasser","200 g fettarmer Frischkäse","ein paar Zehen Knoblauch (gehackt)","1 Päckchen BBQ-Gewürzmischung","50 g BBQ-Sauce","80 g geriebener Mozzarella","Salz & Pfeffer"],"s":["Alle Zutaten in einer Auflaufform gut vermengen.","Mozzarella darüberstreuen.","Form mit Alufolie abdecken.","Bei 200 °C 50 Minuten im Ofen garen, bis alles durch und cremig ist."],"note":"Für 4 Portionen. Die Form wird in der Anleitung nicht genannt."},{"id":"P5","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Hack Banane","k":585,"p":37,"t":"ca. 30 Min","w":0.5,"pt":"ca. 2 Portionen","u":"pro Portion","z":["500 g Rinderhackfleisch","2 Bananen","2 EL Honig","1 EL Zimt","100 g körniger Frischkäse"],"s":["Hack salzen und pfeffern.","Hack in der Pfanne anbraten.","Bananen in Scheiben schneiden.","Sobald das Hack durch ist, die Bananen in die Pfanne geben.","Honig und Zimt zufügen.","Alles gut verrühren.","Die Pfanne vom Herd nehmen.","Körnigen Frischkäse untermischen."],"note":"Für 2 Portionen. Nährwerte gesamt: ca. 1.170 kcal, 74 g Eiweiß, 53 g KH, 58 g Fett. Pro Portion: ca. 585 kcal, 37 g Eiweiß, 27 g KH, 29 g Fett. Je nach Fettgehalt vom Hack leicht abweichend."},{"id":"P6","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Gurkensalat mit Rinderhack","k":216,"p":29,"t":"ca. 30 Min","z":["1 ganze Gurke","2 EL 0% griechischer Joghurt","10 g Jalapeños","10 g Sriracha","15 ml Sojasoße","100 g mageres, gegartes Rinderhack (5 % Fett)","Gewürze nach Wahl hinzufügen"],"s":["Gurke in Stücke schneiden.","Gurke in eine Dose mit Deckel geben.","Übrige Zutaten dazugeben.","Deckel schließen und kräftig schütteln."],"note":"Portionszahl auf der Karte nicht genannt, 1 Portion angenommen. Nährwerte beziehen sich auf die ganze Menge."},{"id":"P7","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Hähnchen-Pesto mit Reis","k":490,"p":42,"t":"45 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["200 g Reis","450 g Hähnchenbrust","70 g Cheddar","50 g Parmesan","50 g Pesto Genovese","200 g Brokkoli (gehackt)","300 g Cherrytomaten","400 ml Hühnerbrühe","Salz und Pfeffer (nach Geschmack)"],"s":["Alle Zutaten außer dem Käse gründlich vermischen.","Cheddar und Parmesan darüberstreuen.","Abdecken.","Im vorgeheizten Ofen bei 190 °C insgesamt 45 Minuten backen.","In den letzten 5 Minuten aufdecken, damit der Käse knusprig wird."],"note":"Für 4 Portionen. Das Original schreibt in den letzten 5 Minuten 'abdecken', gemeint ist offensichtlich aufdecken."},{"id":"P8","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Hähnchen-Pasta Auflauf (mega easy)","k":532,"p":50,"t":"50 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["200 g Pasta nach Wahl (trocken)","600 g Hähnchenbrust, gewürfelt","80 g geriebener Mozzarella","1 Zwiebel","2 Paprika","1 Päckchen Piri-Piri-Gewürz","1 Dose gehackte Tomaten (400 g)","125 g Piri-Piri-Sauce","Salz","Pfeffer"],"s":["Ofen auf 190 °C vorheizen.","Hähnchen, Zwiebel und Paprika klein schneiden.","Alles außer dem Mozzarella in eine große ofenfeste Form geben.","Mit Salz und Pfeffer würzen.","Gut durchmischen.","Mozzarella obenauf verteilen.","Form mit Alufolie abdecken.","45 Minuten abgedeckt backen.","Folie abnehmen und 5 Minuten weiterbacken.","5–10 Minuten ruhen lassen, damit die Flüssigkeit einzieht.","Servieren."],"note":"Für 4 Portionen."},{"id":"P9","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Dessert","n":"High-Protein-Brownies","k":273,"p":21,"t":"ca. 40 Min","w":0.167,"pt":"ca. 6 Portionen","u":"pro Portion","z":["5 Bananen","5 Eier","400 g griechischer Joghurt (2 % Fett)","60 g Proteinpulver","2–3 EL Honig (~50 g)","3 EL Kakaopulver (~30 g)"],"s":["Bananen in einer Schüssel zerdrücken.","Übrige Zutaten dazugeben und verrühren.","Teig in eine Form füllen.","Bei ca. 200 °C Ober-/Unterhitze etwa 30 Minuten backen.","Abkühlen lassen.","In Stücke schneiden."],"note":"Menge für 1 Blech, Portionszahl nicht angegeben. Nährwerte gelten für das ganze Blech. Auf der Karte stehen nur Gesamtwerte, die Stückzahl (6) ist angenommen."},{"id":"P10","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Protein Hähnchen Pizza","k":425,"p":43,"t":"ca. 45 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["Hähnchen Pizzaboden: 450 g Hähnchenhack","Hähnchen Pizzaboden: 2 große Eier","Hähnchen Pizzaboden: ½ Tasse geriebener Parmesan","Hähnchen Pizzaboden: 1 TL Knoblauchpulver","Hähnchen Pizzaboden: 1 TL italienische Gewürze","Hähnchen Pizzaboden: ½ TL Salz","Hähnchen Pizzaboden: ½ TL schwarzer Pfeffer","Toppings: ½ Tasse Pizzasauce","Toppings: 1 Tasse geriebener Mozzarella","Toppings: ca. 10 Scheiben Geflügel-Salami"],"s":["Ofen auf 200 °C vorheizen.","Backblech mit Backpapier auslegen.","Hähnchenhack, Eier, Parmesan und Gewürze gründlich vermischen.","Masse auf das Blech geben.","Masse dünn verstreichen, sonst wird der Boden nicht knusprig.","25 Minuten backen, bis der Boden goldbraun ist.","5 Minuten abkühlen lassen.","Ofen auf 220 °C hochstellen.","Pizzasauce auf dem Boden verteilen.","Mozzarella und Salami darauf verteilen.","Weitere 10 Minuten backen, bis der Käse geschmolzen und der Boden knusprig ist.","Kurz ruhen lassen, dann essen."],"note":"Für 4 Stücke. Nährwerte ganze Pizza: ca. 1.650–1.750 kcal, 165–175 g Protein, 95–105 g Fett, 15–25 g KH. Pro Stück: ca. 410–440 kcal, 40–44 g Protein, 24–26 g Fett, 4–6 g KH."},{"id":"P11","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Wraps","k":360,"p":42,"t":"ca. 40 Min","w":0.5,"pt":"ca. 2 Portionen","u":"pro Portion","z":["250 g körniger Frischkäse (Magerstufe 0,2 %)","2 Eier","15 g Parmesan","65 g Light-Mozzarella","50 g Putenschinken","40 g getrocknete Tomaten","1 Handvoll Rucola","Italienische Kräuter"],"s":["Eier, Parmesan, Kräuter und Frischkäse fein pürieren.","Im vorgeheizten Ofen bei 180 °C Ober-/Unterhitze 25–30 Minuten backen.","Der Boden muss so fest sein, dass er sich aufrollen lässt.","Mit Mozzarella, Putenschinken, Tomaten und Rucola belegen.","Aufrollen.","Der Länge nach halbieren."],"note":"Kochschinken durch Putenschinken ersetzt. Für 2 Portionen, Nährwerte pro Portion (½)."},{"id":"P12","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Futter","k":417,"p":46,"t":"ca. 60 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["600 g Kartoffeln","650 g Hähnchenbrustfilet","240 g Kichererbsen (1 Dose)","1 Paprika","1 Zucchini","10 ml Olivenöl","4 Knoblauchzehen","1 Zitrone (Saft)","Paprikapulver, Rosmarin, Salz, Pfeffer (je 1 EL)"],"s":["Kartoffeln in Stücke schneiden.","Kartoffeln, Hähnchenfilet, Paprika, Zucchini und Kichererbsen in eine Form geben.","Olivenöl, Paprikapulver, Rosmarin, Salz, Pfeffer und Zitronensaft verrühren.","Marinade über Hähnchen und Kartoffeln gießen.","Alles gut durchmischen.","Im vorgeheizten Ofen bei 180 °C etwa 50 Minuten backen.","Kurz abkühlen lassen."],"note":"Für 4 Portionen, Nährwerte pro Portion (0,25). Zucchini und Knoblauch tauchen in den Schritten nicht auf, vermutlich mit in die Form geben."},{"id":"P13","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High Protein Buffalo Chicken Hotpockets","k":345,"p":31,"t":"ca. 14 Min","w":0.125,"pt":"ca. 8 Portionen","u":"pro Portion","z":["Buffalo Chicken Würzmischung: 500 g Hähnchenbrust (in kleine Würfel geschnitten)","1 TL Knoblauchpulver","1 TL Zwiebelpulver","1 TL geräuchertes Paprikapulver","½ TL Cayennepfeffer (optional für extra Schärfe)","1 TL Salz","1 TL Pfeffer","Hot Pocket Teig: 400 g Weizenmehl","410 g griechischer Joghurt (0 %)","optional: Salz nach Geschmack","Buffalo Chicken Sauce: 130 ml scharfe Soße (z. B. Frank's Red Hot)","30 g leichte Butter (z. B. Lurpak Light)","1 EL Apfelessig","20 g brauner Zuckerersatz (alternativ brauner Zucker oder Süßungsmittel)","25 g Honig","1 TL Maisstärke, vermischt mit 2 TL Wasser","Zum Füllen: 20 g fettarmer, geriebener Käse pro Pocket (z. B. 50 % weniger Fett)"],"s":["Aus den Teigzutaten einen Teig kneten.","Hähnchenwürfel mit den Gewürzen würzen.","Hähnchen anbraten und beiseitestellen.","In derselben Pfanne die Butter zerlassen.","Scharfe Soße, Apfelessig, Honig, braunen Zucker und Maisstärke-Mischung dazugeben und kurz aufkochen.","Hähnchen zurück in die Soße geben.","Gesamte Füllung abwiegen und durch 8 teilen.","Pro Pocket 20 g geriebenen Käse bereithalten.","Ein Achtel des Teigs ausrollen.","Ein Achtel der Füllung auf dem Teig verteilen, Rand freilassen.","Käse daraufgeben.","Rand zur Mitte hin zuklappen.","Pocket wenden und leicht flach drücken.","In einer Pfanne mit etwas Öl bei mittlerer Hitze braten.","Deckel auflegen und 3–4 Minuten pro Seite garen."],"note":"Ergibt 8 Pockets, Nährwerte pro Stück: 345 kcal, 31 g Protein. Die 8 ergibt sich aus der Teilung durch 8. Geeignet für Meal Prep."},{"id":"P14","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Tortilla-Quiche-Rezept","k":201,"p":15,"t":"ca. 30 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["1 mittelgroßer Wrap","4 Eier","75 g fettarmer Hüttenkäse","30 g leichter Cheddar","30 g Parmesan","50 g Feta","100 g Cherrytomaten","1 Handvoll Spinat","Salz und Pfeffer"],"s":["Wrap in eine Pfanne legen.","Spinat, Eier, Tomaten, Hüttenkäse und Feta gut vermischen.","Mischung auf den Wrap geben.","Cheddar und Parmesan darüberstreuen.","Im vorgeheizten Ofen bei 180 °C 20 Minuten backen."],"note":"Für 4 Portionen. Die Pfanne muss ofenfest sein (nicht ausdrücklich angegeben)."},{"id":"P15","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Wraps zum Mealprep","k":400,"p":35,"t":"ca. 17 Min","w":0.2,"pt":"ca. 5 Portionen","u":"pro Portion","z":["5 Tortilla-Wraps","400 g gegarte Hähnchenbrust","100 g Light-Käse","100 g Light-Mayo","300 g Cherrytomaten","1 rote Paprika (gehackt)","0,25 Packung Fajita-Gewürzmischung, oder eine andere Mischung nach Geschmack"],"s":["Wraps mit allen Zutaten gleichmäßig belegen.","Wraps fest einrollen.","Etwa 6–7 Minuten im Airfryer garen."],"note":"Ergibt 5 Wraps. Pro Wrap ca. 400 kcal und ca. 35 g Protein. Im Kühlschrank 3–4 Tage haltbar. Aufwärmen im Airfryer bei 200 °C für 6–7 Minuten. Einfrieren möglich: erst bei 170 °C 10 Minuten in Alufolie, dann Folie ab, mit Öl besprühen und bei 200 °C 12–15 Minuten fertig garen. Nur so viele vorbereiten, wie in 3–4 Tagen gegessen werden."},{"id":"P16","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Die beste Homemade Pizza","k":832,"p":67,"t":"30 Min","z":["500 g Hüttenkäse (Cottage Cheese)","250 g Weizenmehl","1 TL Backpulver","1 TL gehackter Knoblauch","1 TL Salz","120 g Tomatensoße / Pizzasoße","175 g fettarmer Mozzarella","optional: Hähnchen, Rinderhack, Veggiehack etc. für noch mehr Protein"],"s":["Körnigen Frischkäse mixen.","Mit Mehl, Backpulver, Knoblauch und Salz zu einem Teig verkneten.","Teig dünn auf Backpapier ausbreiten.","Rand etwa 1 cm einrollen, so entsteht der Pizzarand.","Tomatensoße mit einem Schuss Olivenöl verrühren.","Soße auf dem Teig verteilen.","Mit Oregano und Basilikum würzen.","Mozzarella darauf verteilen.","25–30 Minuten backen."],"note":"Portionszahl nicht genannt, Nährwerte pro Portion (½), also 2 Portionen. Backen bei 180–200 °C, je nach Teigdicke und gewünschter Knusprigkeit. Olivenöl nur als Schuss ohne Menge."},{"id":"P17","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Dessert","n":"Protein-Schoko-Eis","k":183,"p":13,"t":"2 Std. einfrieren","w":0.333,"pt":"ca. 3 Portionen","u":"pro Portion","z":["300 g körniger Frischkäse","3 EL Honig","2 EL Kakaopulver (oder Backkakao)","1 Banane"],"s":["Alle Zutaten im Mixer cremig pürieren.","Masse in einen Behälter füllen.","2 Stunden einfrieren.","Vor dem Servieren 10 Minuten antauen lassen, dann lässt es sich leichter portionieren."],"note":"Reicht für 2–3 Portionen, hier mit 3 angesetzt. Nährwerte für die gesamte Menge."},{"id":"P18","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein Käse-Knoblauch-Hähnchen-Wraps","k":335,"p":37,"t":"ca. 20 Min","w":0.125,"pt":"ca. 8 Portionen","u":"pro Portion","z":["650 g Hähnchenbrust (gewürfelt)","1 TL Knoblauchpulver","1 TL geräuchertes Paprikapulver","½ TL Cayennepfeffer","1 TL Salz","1 TL Pfeffer","Für die Knoblauchsauce: 200 g körniger Frischkäse (0 % Fett)","60 g griechischer Joghurt (0 % Fett)","50 g leichte Mayo","20 g Knoblauchpaste bzw. Knoblauchpulver","Saft von ½ Zitrone","1 TL Honig","½ TL Salz","½ TL schwarzer Pfeffer","Weitere Zutaten: 80 g geriebener Mozzarella","80 g geriebener Cheddar","gehackte Petersilie","8 Protein-Tortillas"],"s":["Hähnchen mit allen Gewürzen vermischen.","Hähnchen anbraten.","Zutaten der Knoblauchsauce gut mixen.","Hähnchen, Sauce, Käse und Petersilie vermengen.","Füllung auf die 8 Wraps verteilen.","Wraps einrollen.","Bei 200 °C 8–10 Minuten backen."],"note":"Ergibt 8 Wraps, pro Stück 335 kcal und 37 g Protein. In Alufolie im Kühlschrank einige Tage haltbar. Aufwärmen: in feuchtes Küchenpapier wickeln, 5–6 Minuten in die Mikrowelle, danach in Pfanne oder Airfryer knusprig machen."},{"id":"P19","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Veggie-High-Protein-Quiche","k":233,"p":18,"t":"ca. 32 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["1 Vollkorn-Tortilla","4 Eier","100 g Champignons","20 g Feta","100 g körniger Frischkäse","50 g Parmesan","50 g Brokkoli","80 g Paprika","100 g Tomaten","Salz, Pfeffer & Knoblauchpulver"],"s":["Tortilla in eine hitzebeständige Pfanne oder Auflaufform legen.","Alle Zutaten außer dem Parmesan gut vermischen.","Mischung auf die Tortilla geben.","Parmesan darüberstreuen.","Im vorgeheizten Ofen bei 180 °C 20–22 Minuten backen."],"note":"Für 4 Portionen, Nährwerte pro Portion (0,25). Vor dem Essen kurz abkühlen lassen."},{"id":"P20","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Beilage","n":"Airfryer Knoblauch-Pizza","k":450,"p":22,"t":"ca. 15 Min","z":["2 Mini-Tortilla-Wraps","30 g leichte Butter","20 g Knoblauchpaste","60 g Mozzarella","etwas italienische Kräuter"],"s":["Butter und Knoblauchpaste in ein hitzebeständiges Gefäß geben.","Im Airfryer erhitzen. Vorsicht, heiß.","Etwas Knoblauchbutter auf einem Wrap verteilen.","Mozzarella daraufgeben.","Zweiten Wrap darauflegen.","Wieder Knoblauchbutter und Mozzarella verteilen.","Mit Oregano und italienischen Kräutern bestreuen.","Bei 200 °C 5 Minuten im Airfryer garen."],"note":"Passt als Beilage oder Snack. Nährwerte: 450 kcal, 22 g Protein, Bezugsgröße nicht angegeben. Schritt 1 nennt 'Alioli', in den Zutaten steht Knoblauchpaste, hier als Knoblauchpaste übernommen. Oregano im Schritt, aber nicht in der Zutatenliste."},{"id":"P21","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Mongolian Beef Nudeln","k":401,"p":41,"t":"ca. 30 Min","w":0.333,"pt":"ca. 3 Portionen","u":"pro Portion","z":["170 g beliebige Nudeln","Mongolian Beef: 1 TL Sesamöl (oder Olivenöl)","1 EL gehackter Knoblauch","1 EL gehackter Ingwer","500 g mageres Rinderhack (93 % mager)","1 TL Pfeffer","⅓ Tasse Sojasoße","0,25 Tasse Brühe (oder Wasser)","1 TL Maisstärke + 0,25 Tasse Wasser (Pfeilwurzelstärke geht auch)","2 EL Süßungsmittel (z. B. brauner Rohrzucker)","Optional: Frühlingszwiebeln, Sesamsamen und Chiliflocken"],"s":["Die Nudeln nach Packungsangabe garen.","Das Öl in einer Pfanne erhitzen.","Ingwer und Knoblauch kurz darin anbraten.","Das Hack dazugeben, salzen und pfeffern.","Das Hack durchbraten.","Sojasauce, Brühe, Maisstärke und Wasser einrühren.","Den Zucker unterrühren.","Die Sauce kurz köcheln lassen.","Die Nudeln unter das Hack mischen.","Mit Frühlingszwiebeln und Sesam bestreuen."],"note":"Schnell gemacht. Angaben für 3 Portionen, Nährwerte pro Portion."},{"id":"P22","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein Airfryer Pizza in 10 Min","k":508,"p":43,"t":"10 Min","z":["2 Protein-Wraps (je ca. 124 kcal)","80 g Light-Gouda (gerieben)","4 Scheiben Geflügel-Salami","Etwas passierte Tomaten","Optional: etwas Light-Streukäse als Topping"],"s":["Beide Wraps mit passierten Tomaten bestreichen.","Etwas Käse darauf verteilen.","Die Wraps übereinanderlegen. So wird der Boden schön knusprig.","Wraps für 5–6 Minuten bei ca. 180–200 °C in den Airfryer geben.","Salami und den übrigen Käse auf den Wraps verteilen.","Nochmals kurz in den Airfryer geben, bis der Käse geschmolzen ist.","Herausnehmen und in Stücke schneiden."],"note":"Dauer ca. 10 Minuten. Nährwerte pro Pizza: 508 kcal, 43 g Eiweiß."},{"id":"P23","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Dessert","n":"Protein-Kuchen","k":204,"p":23,"t":"45 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["300 g Magerquark","200 g Frischkäse light","1 Päckchen Puddingpulver","80 ml Wasser","Süßstoff","2 Eier","30 g Whey Protein","Optional: Früchte (z. B. Mandarinen aus der Dose)"],"s":["Alle Zutaten zu einer glatten Masse verrühren.","Die Masse in eine Kuchenform füllen.","Die Form abdecken.","Den Kuchen ca. 45 Minuten bei 180 °C backen.","Den Kuchen abkühlen lassen."],"note":"Nährwerte für den ganzen Kuchen: ca. 814 kcal, 92 g Protein, 59 g Kohlenhydrate, 20 g Fett. Portionszahl nicht angegeben. Auf der Karte stehen nur Gesamtwerte, die Stückzahl (4) ist angenommen."},{"id":"P24","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Snack / Pause","n":"Protein-Snack zum Einfrieren","k":151,"p":20,"t":"4 Std. einfrieren","w":0.2,"pt":"ca. 5 Portionen","u":"pro Portion","z":["450 g Griechischer Joghurt (0 %)","60 g Whey Protein (2 Messlöffel)","100 g Beeren","1 EL Honig","20 g Zartbitterschokolade"],"s":["Alle Zutaten außer der Schokolade gründlich verrühren.","Die Masse auf einem Backblech verstreichen.","Die Schokolade schmelzen.","Die geschmolzene Schokolade über die Masse geben.","Das Blech 3–4 Stunden ins Gefrierfach stellen."],"note":"Ergibt 5 Portionen, Nährwerte pro Portion (⅕)."},{"id":"P25","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"One-Pot-Rezept mit Orzo, Hähnchen und Gemüse","k":505,"p":45,"t":"45 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["160 g Orzo-Nudeln","320 g Hähnchenbrust","180 g Kichererbsen (aus der Dose, abgetropft, ohne zugesetztes Salz)","150 g Brokkoli","150 g rote Zwiebel","150 g Champignons","100 g Spinat","80 g getrocknete Tomaten (in Öl, abgetropft)","100 g Parmesan","2 Knoblauchzehen","1 EL Paprikapulver","400 ml Hühnerbrühe"],"s":["Alle Zutaten in einer Auflaufform vermischen.","Die Form mit Alufolie abdecken.","Im vorgeheizten Ofen bei 190 °C 35 Minuten backen.","Die Folie abnehmen.","Weitere 10 Minuten backen, bis die Oberfläche knusprig ist.","Vor dem Servieren etwas Zitronensaft darüberträufeln."],"note":"Gut für Meal Prep, 4 Portionen. Pro Portion zusätzlich 7 g Ballaststoffe. Zitronensaft ist nicht in der Zutatenliste."},{"id":"P26","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Ofengericht mit Feta, Hähnchen und Süßkartoffeln","k":510,"p":43,"t":"30 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["500 g Süßkartoffel","500 g Hähnchenbrust","150 g Feta-Käse","240 g Kichererbsen (abgetropft)","200 g Brokkoli","200 g Zwiebel","4 ml Olivenöl","Salz, Knoblauchgranulat, Kräutermischung und Pfeffer","Dressing: 100 g fettarmer griechischer Joghurt","Dressing: 10 g Tahini","Dressing: 1 EL Kreuzkümmel","Dressing: Saft einer Zitrone","Dressing: 1 Prise Salz","Dressing: 50 ml Wasser (zum Verdünnen)"],"s":["Süßkartoffel, Brokkoli, Zwiebel und zerbröckelten Feta auf einem Backblech verteilen.","Kräftig würzen.","Im vorgeheizten Ofen bei 200 °C 30 Minuten rösten.","Das Hähnchen dazugeben.","Weitere 20–25 Minuten garen.","Joghurt, Tahini, Kreuzkümmel, Zitronensaft, Salz und Wasser glatt rühren.","Das Dressing über das Ofengericht träufeln."],"note":"Gut für Meal Prep, 4 Portionen, Nährwerte pro Portion (¼)."},{"id":"P27","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein Chicken Calzone","k":410,"p":53,"t":"25 Min","w":0.5,"pt":"ca. 2 Portionen","u":"pro Portion","z":["400 g Hähnchenbrust","100 g Frischkäse","½ Paprika, gewürfelt","ca. 40 g Käse (Scheiben und etwas gerieben)","etwas Tomate (optional, dünn)","Salz, Pfeffer und Gewürze nach Geschmack"],"s":["Die Hähnchenbrust im Mixer fein pürieren.","Die Masse auf Backpapier zu einem Rechteck streichen.","Frischkäse, Paprika und Käse darauf verteilen.","Optional dünne Tomatenscheiben dazulegen.","Das Backpapier zusammenklappen, sodass die Calzone geschlossen ist.","Etwas geriebenen Käse darüberstreuen.","25 Minuten bei 190 °C im Ofen oder Airfryer backen, bis alles goldbraun und gar ist."],"note":"Low Carb und sättigend. Ergibt 2 Stück. Gesamt: ca. 820 kcal, 105 g Protein, 14 g Kohlenhydrate, 36 g Fett. Pro Stück: ca. 410 kcal, 52 g Protein, 7 g Kohlenhydrate, 18 g Fett."},{"id":"P28","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Frühstück","n":"High Protein Breakfast Crunch Wraps","k":524,"p":54,"t":"ca. 30 Min","w":0.167,"pt":"ca. 6 Portionen","u":"pro Portion","z":["Crispy Beef Tortillas: 500 g mageres Rinderhack (5 % Fett oder weniger)","Crispy Beef Tortillas: 20 g Taco-Gewürz","Crispy Beef Tortillas: 6 Mini-Tortillas (ca. 24 g, gern Low-Carb-Variante)","Rührei: 10 Eier","Rührei: etwas Öl","Cremige Sauce: 60 g zuckerarmer Ketchup","Cremige Sauce: 60 g Light-Mayo","Cremige Sauce: 70 g Griechischer Joghurt","Pro Crunchwrap: 1 Protein-Tortilla (Mission Protein Tortillas)","Pro Crunchwrap: ⅙ der Sauce","Pro Crunchwrap: ⅙ der Rühreier","Pro Crunchwrap: gehackter Schnittlauch","Pro Crunchwrap: 25 g fettarmer, geriebener Käse","Pro Crunchwrap: 1 Crispy Beef Tortilla"],"s":["Das Hack mit dem Taco-Gewürz würzen.","Die Masse bis zum Rand flach auf eine Mini-Tortilla drücken.","Die Tortilla mit der Hackseite nach unten in die Pfanne legen.","Braten, bis das Hack durch ist.","Eine Scheibe Käse darauflegen.","Die Tortilla aus der Pfanne nehmen.","Das Rührei in der Pfanne braten.","Ketchup, Mayo und Joghurt zur Sauce verrühren.","Auf eine große Protein-Tortilla ⅙ der Sauce streichen.","⅙ des Rühreis und den Käse daraufgeben. Den Rand frei lassen.","Die Mini-Tortilla mit der Hackseite nach unten in die Mitte legen.","Den Rand der großen Tortilla zur Mitte hin einschlagen.","Den Crunchwrap in der Pfanne von beiden Seiten knusprig braten."],"note":"Ergibt 6 Wraps mit je ca. 54 g Protein, Nährwerte pro Wrap. Gut für Meal Prep: abgekühlt in Alufolie wickeln, 2–3 Tage im Kühlschrank haltbar. Der Käse auf der Hack-Tortilla (Scheibe) steht nicht gesondert in der Zutatenliste; Schnittlauch kommt im Text nicht vor."},{"id":"P29","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Beilage","n":"High-Protein Eiersalat-Aufstrich","k":690,"p":72,"t":"ca. 30 Min","z":["4 Eier","1 Avocado (ca. 100 g)","450 g Griechischer Joghurt (0 %)","50 g rote Zwiebel","50 g Gurke","Saft von 1 Zitrone","1 EL Dijon-Senf","Salz und Pfeffer","Optional: etwas Tabasco"],"s":["Die Eier hart kochen, schälen und klein hacken.","Zwiebel, Gurke und Avocado fein würfeln.","Alles in eine Schüssel geben.","Senf, Zitronensaft und Joghurt dazugeben.","Gründlich mischen und abschmecken."],"note":"Ergibt 1 Schüssel, Nährwerte für die ganze Schüssel. Passt als Brotaufstrich."},{"id":"P30","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Beilage","n":"Protein-Käse-Knoblauch-Naan","k":285,"p":21,"t":"ca. 30 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["190 g Mehl + 1 TL Backpulver","250 g griechischer Joghurt","1 Prise Salz","120 g fettarmer Käse","Kochspray oder Öl","Knoblauchbutter (optional): 2 EL leichte Butter","Knoblauchbutter (optional): 1 TL Knoblauchpaste","Knoblauchbutter (optional): gehackte Petersilie"],"s":["Mehl (mit Backpulver), Joghurt und Salz verrühren, bis ein grober Teig entsteht.","Den Teig 5–10 Minuten ruhen lassen. So klebt er weniger und lässt sich besser formen.","Den Teig in 4 Stücke teilen.","Die Stücke flach drücken oder ausrollen.","Den Käse in die Mitte geben.","Den Teig zusammenklappen und leicht andrücken.","Die Pfanne auf mittlere Hitze stellen und mit Kochspray einsprühen.","Die Naans von beiden Seiten goldbraun braten.","Optional: Knoblauchbutter darüberstreichen."],"note":"Ergibt 4 Naans. Pro Naan ohne Butter: 285 kcal, 21 g Protein, 38 g Kohlenhydrate, 5 g Fett. Mit Butter: 326 kcal, 21,5 g Protein, 39 g Kohlenhydrate, 10 g Fett. Für 6 Naans die Menge mit 1,5 multiplizieren."},{"id":"P31","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Chicken-Chorizo-Gericht mit weißen Bohnen","k":490,"p":41,"t":"50 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["200 g Orzo","400 g Hähnchenbrust, gekocht","50 g Geflügel-Chorizo oder Paprikawurst vom Geflügel","125 g Mozzarella","240 g weiße Riesenbohnen (abgetropft)","500 g Tomaten (gehackt oder frisch)","150 g Zwiebeln","3–4 Knoblauchzehen","1 Handvoll Spinat","500 ml Gemüsebrühe","Salz, Pfeffer, Paprika, Chili"],"s":["Alle Zutaten außer Mozzarella und Hähnchen in einer großen Auflaufform mischen.","Die Brühe darübergießen.","Den Mozzarella im Ganzen obenauf legen.","Die Form abdecken.","Im vorgeheizten Ofen bei 200 °C ca. 50 Minuten backen.","Das gekochte Hähnchen zerzupfen.","Das Hähnchen unterrühren.","Mit frischem Basilikum bestreuen."],"note":"Chorizo ersetzt durch Geflügel-Chorizo oder Paprikawurst vom Geflügel. 4 Portionen. Gesamt: 1.960 kcal, 163 g Eiweiß, 135 g Kohlenhydrate, 63 g Fett. Pro Portion: 490 kcal, 41 g Eiweiß, 34 g Kohlenhydrate, 16 g Fett. Basilikum steht nicht in der Zutatenliste."},{"id":"P32","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Easy Meal Prep (Kartoffel-Hack-Auflauf)","k":640,"p":65,"t":"30 Min","z":["250 g Kartoffeln","200 g mageres Rinderhack (ca. 5 % Fett)","40 g Frischkäse light","30 g geriebener Käse light (zum Überbacken)","1 EL Light-Mayo","etwas Light-Ketchup","Zwiebeln","Knoblauchpulver, Salz und Pfeffer"],"s":["Die Kartoffeln in eine Schüssel geben.","Hack, Frischkäse, Mayo, Ketchup und Gewürze dazugeben.","Alles gut vermengen.","Die Masse in eine Auflaufform füllen.","Den geriebenen Käse obenauf streuen.","Im vorgeheizten Ofen bei 200 °C Ober-/Unterhitze 25–30 Minuten backen, bis der Käse goldbraun ist.","Kurz abkühlen lassen."],"note":"Eine Portion, ca. 640 kcal, 65 g Protein, 53 g Kohlenhydrate, 20 g Fett. Alles mischen, wenig Käse obenauf. Zwiebelmenge und Kartoffelzustand (roh oder vorgegart) sind im Original nicht angegeben."},{"id":"P33","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Spinat-Auflauf mit Hüttenkäse (Proteinbombe)","k":500,"p":55,"t":"30 Min","z":["50 g Spinat","3 mittelgroße Eier","300 g Hüttenkäse (fettreduziert)","etwas Paprikapulver","30 g Mozzarella"],"s":["Den Ofen auf 180 °C vorheizen.","Spinat, Eier, Hüttenkäse, Salz und Paprikapulver in eine Schüssel geben.","Alles gut verrühren.","Den Mozzarella darüberstreuen.","Ca. 30 Minuten backen."],"note":"Nährwerte ca.: 500 kcal, 55 g Eiweiß, 20 g Kohlenhydrate, 23 g Fett (Bezugsgröße nicht angegeben). Salz fehlt in der Zutatenliste."},{"id":"P34","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Dessert","n":"Apfel Protein Kuchen","k":75,"p":8,"t":"40 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["1 Apfel (entkernt und geschält)","30 g Proteinpulver (neutral oder Vanille)","2 EL Kakaopulver (ungesüßt)","1 großes Ei","1 TL Backpulver"],"s":["Den Apfel schälen und entkernen.","Apfel, Proteinpulver, Kakao, Ei und Backpulver glatt mixen.","Eine Form einfetten und mit Backpapier auslegen.","Den Teig in die Form füllen.","Bei 175 °C ca. 40 Minuten backen, bis ein Zahnstocher sauber bleibt.","Den Kuchen vollständig abkühlen lassen."],"note":"Nährwerte für das ganze Rezept: ca. 300 kcal, 33 g Protein, 26 g Kohlenhydrate, 8 g Fett. Portionszahl nicht angegeben. Auf der Karte stehen nur Gesamtwerte, die Stückzahl (4) ist angenommen."},{"id":"P35","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High-Protein-Dinner (Reis-Hähnchen-Auflauf)","k":557,"p":41,"t":"40 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["200 g Reis","500 g Hähnchenbrust","100 g Cheddar-Käse","2 Paprika (gemischt)","250 g Tomaten","1 rote Zwiebel","1 Limette","200 g Saure Sahne","Salz, Pfeffer, Kreuzkümmel, Paprika","350 ml Wasser"],"s":["Alles außer dem Käse in einer Auflaufform gut vermischen.","Den Cheddar darüberstreuen.","Die Form abdecken.","Bei 200–220 °C 40 Minuten im Ofen backen.","Die Abdeckung entfernen.","Weitere 10–15 Minuten backen, bis der Käse goldbraun ist.","5 Minuten ruhen lassen."],"note":"4 Portionen. Ganzer Auflauf: ca. 2227 kcal, 165 g Protein, 200 g Kohlenhydrate, 80 g Fett. Pro Portion: ca. 557 kcal, 41 g Protein, 50 g Kohlenhydrate, 20 g Fett."},{"id":"P36","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"Protein-Frittata","k":219,"p":21,"t":"20 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["4 Eier","100 g Hüttenkäse (0 % Fett)","40 g Putenschinken in Scheiben","100 g Mozzarella","20 g Parmesan","100 g Paprika","50 g Spinat","Salz und Pfeffer"],"s":["Eier, Hüttenkäse, Paprika, Spinat, Salz und Pfeffer in einer Auflaufform vermengen.","Mozzarella und Putenschinken obenauf verteilen.","Den Parmesan darüberstreuen.","Im vorgeheizten Ofen bei 180 °C 20 Minuten backen."],"note":"Parmaschinken ersetzt durch Putenschinken in Scheiben. 4 Portionen. Pro Portion: 219 kcal, 21 g Protein, 4 g Kohlenhydrate, 13 g Fett, 1 g Ballaststoffe."},{"id":"P37","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High Protein – Low Calorie Pizza","k":255,"p":25,"t":"20 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["400 g körniger Frischkäse","ca. 50 ml Milch","ca. 50 g geriebener Käse","ca. 60 g Mehl","2–3 Eier","Belag nach Wahl: Paprika, Champignons, Putenschinken oder anderes"],"s":["Alle Zutaten in einer Schüssel vermengen.","Die Masse auf ein Backblech streichen.","Bei 180 °C ca. 20 Minuten backen, bis die Pizza goldbraun ist."],"note":"Schinken ersetzt durch Putenschinken. 4 Portionen (4 Stücke). Pro Portion Bereiche: ca. 245–265 kcal, 24–26 g Eiweiß, 11–13 g Fett, 9–11 g Kohlenhydrate. Werte hängen von Käse und Schinken ab."},{"id":"P38","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Snack / Pause","n":"Knusprige Babybel aus dem Airfryer","k":55,"p":6,"t":"10 Min","w":0.2,"pt":"ca. 5 Portionen","u":"pro Portion","z":["5 Babybel Light","1 Ei","Paniermehl"],"s":["Die Babybel auspacken.","Das Ei verquirlen.","Das Paniermehl in eine zweite Schüssel geben.","Jeden Babybel erst im Ei, dann im Paniermehl wenden.","Den Vorgang einmal wiederholen: Ei, dann Paniermehl.","Die Babybel in den Airfryer legen.","10 Minuten bei 195 °C garen.","Kurz abkühlen lassen."],"note":"Ergibt 5 Stück. Gesamt: ca. 275 kcal, 30 g Protein, 15 g Kohlenhydrate, 15 g Fett. Pro Babybel: ca. 55 kcal, 6 g Protein, 3 g Kohlenhydrate, 3 g Fett."},{"id":"P39","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High Protein Chicken Fajita Wraps","k":450,"p":45,"t":"35 Min","w":0.25,"pt":"ca. 4 Portionen","u":"pro Portion","z":["500 g Hähnchenbrust","4 mittelgroße Wraps","35 g Parmesan","60 g getrocknete Tomaten","2 Paprika","2 Zwiebeln","1 EL Olivenöl","Saft von 1 Zitrone","Paprikapulver, Kreuzkümmel, Knoblauchpulver, Salz und Pfeffer","Sauce: 200 g fettarmer griechischer Joghurt","Sauce: 30 g Sriracha","Sauce: geräuchertes Paprikapulver, Salz und Pfeffer nach Geschmack"],"s":["Hähnchen, geschnittenes Gemüse und Gewürze auf ein Backblech geben.","Den Parmesan darüberstreuen.","Bei 180 °C ca. 30–35 Minuten backen.","Die heiße Fajita-Mischung auf die Wraps verteilen.","Joghurt, Sriracha und Gewürze zur Sauce verrühren.","Die Sauce über die Füllung geben.","Die Wraps einrollen."],"note":"Gut für Meal Prep, 4 Portionen. Pro Portion: ca. 450 kcal, 45 g Protein, 34 g Kohlenhydrate, 13 g Fett."},{"id":"P40","q":"Rezeptsammlung von @mfreimannfitness (Zubereitung in eigenen Worten)","c":"Hauptmahlzeit (16 Uhr)","n":"High Protein Chicken Burrito","k":535,"p":38,"t":"ca. 30 Min","z":["1 Vollkorn-Wrap","ca. 120 g Putenhack oder Fleischersatz (vegane Option möglich)","ca. 50 g gekochter Reis","ca. 30 g geriebener Käse","1 EL Salsa-Dip","1 EL Guacamole","1–2 EL passierte Tomaten","etwas Salat"],"s":["Den Reis kochen, falls noch nicht geschehen.","Öl in einer Pfanne erhitzen.","Hack oder Alternative darin garbraten.","Würzen.","Auf dem Wrap Tomaten, Käse, Hack, Salsa, Guacamole und Reis verteilen.","Etwas Salat obendrauf legen.","Den Wrap einrollen.","Kurz anrösten."],"note":"Menge für 1 Burrito, auch vegetarisch oder vegan möglich. Pro Burrito Bereiche (geschätzt): ca. 520–550 kcal, 35–40 g Protein, 20–25 g Fett, 40–45 g Kohlenhydrate. Öl wird im Schritt genannt, fehlt aber in der Zutatenliste."}];
